const byTool = new Map(OPEN_CONNECTOR_CHAT_TOOLS.map((item) => [item.tool, item]));

export function getOpenConnectorChatTool(toolName: unknown): OpenConnectorChatTool | null {
  return byTool.get(String(toolName || '')) || null;
}

